class Solution:
    def numberOfSequence(self, n: int, sick: List[int]) -> int:
        MOD = 10**9 + 7

        # Precompute factorials and inverse factorials
        max_n = n + 1
        fact = [1] * max_n
        for i in range(1, max_n):
            fact[i] = fact[i-1] * i % MOD

        inv_fact = [1] * max_n
        inv_fact[max_n - 1] = pow(fact[max_n - 1], MOD - 2, MOD)
        for i in range(max_n - 2, -1, -1):
            inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD

        def comb(n, k):
            if k < 0 or k > n:
                return 0
            return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

        # Find segments between sick children
        segments = []

        # Left segment (before first sick child)
        if sick[0] > 0:
            segments.append((sick[0], True))  # True means it's an end segment

        # Middle segments (between sick children)
        for i in range(len(sick) - 1):
            gap = sick[i + 1] - sick[i] - 1
            if gap > 0:
                segments.append((gap, False))  # False means it's a middle segment

        # Right segment (after last sick child)
        if sick[-1] < n - 1:
            segments.append((n - 1 - sick[-1], True))

        # Calculate total number of sequences
        total = sum(seg[0] for seg in segments)
        result = fact[total]

        # For each segment, divide by its factorial and multiply by 2^(size-1) if it's a middle segment
        for size, is_end in segments:
            result = result * inv_fact[size] % MOD
            if not is_end and size > 0:
                result = result * pow(2, size - 1, MOD) % MOD

        return result
